import { connection } from 'next/server'

export default async function TimestampPage() {
  // Opt out of static prerendering: connection() waits for an incoming
  // request before rendering, so this is excluded from the build-time
  // prerender and runs on every request instead.
  await connection()

  const timestamp = new Date().toISOString()

  return (
    <main>
      <h1>Server Timestamp</h1>
      <p>This timestamp is generated fresh on every request:</p>
      <time dateTime={timestamp}>{timestamp}</time>
    </main>
  )
}

